INSERT INTO client_boards (board_data) VALUES ($${"id":"board-20","name":"Vestd","initials":"V","color":"#FF6B6B","groups":[{"id":"group-20-0","title":"Other Tasks","color":"#FF6B6B","tasks":[{"id":"task-20-0-0","title":"Seis related","status":"status-2","priority":"priority-4","dueDate":"2025-10-14","assignedTo":["f9f11222-d2a9-4ae8-a327-8c4621d90b7c","a1e57188-a322-42b2-9d33-b5df08033685"],"worksheet":"","clientSheet":"","comments":[{"id":"comment-20-0-0-0","author":"Ben Lowe","text":"@Ben One thing I noticed when looking for SEIS-related rankings is the sheer number of help centre articles that are ranking, above other pages on the main website.  This is far from ideal. Ideally we'd want pillar / product pages and blog posts ranking above help centre pages, which are can sometimes point to external sites (e.g. gov.uk) and are rarely optimised for conversion.  Can you investigate on a wider basis so we can see this split at a global level?","timestamp":"2025-08-14T00:59:41","avatar":""}]},{"id":"task-20-0-1","title":"https://www.vestd.com/shared-ownership-calculator Check why clicks have fallen","status":"status-2","priority":"priority-4","dueDate":"2025-11-12","assignedTo":"a1e57188-a322-42b2-9d33-b5df08033685","worksheet":"","clientSheet":"https://docs.google.com/document/d/1GSwvSNkKo9lAFN6DugxM5KXq1_OA1jmizoJ627B6Uxw/edit?tab=t.0","comments":[{"id":"comment-20-0-1-0","author":"Ben Lowe","text":"https://www.vestd.com/shared-ownership-calculator","timestamp":"2025-09-04T12:17:23","avatar":""},{"id":"comment-20-0-1-1","author":"Ben Lowe","text":"do a content audit of this page @Janin Canonero","timestamp":"2025-09-22T06:55:23","avatar":""},{"id":"comment-20-0-1-2","author":"Ben Lowe","text":"@Janin Canonero is this done?","timestamp":"2025-10-20T02:01:03","avatar":""},{"id":"comment-20-0-1-3","author":"Janin Canonero","text":"yeah boss kindly check","timestamp":"2025-10-21T12:24:55","avatar":""},{"id":"comment-20-0-1-4","author":"Ben Lowe","text":"Need to review this","timestamp":"2025-11-12T18:40:44","avatar":""}]},{"id":"task-20-0-2","title":"Reddit Threads with questions for Vestd","status":"status-8","priority":"priority-4","dueDate":"2025-11-12","assignedTo":"a1e57188-a322-42b2-9d33-b5df08033685","worksheet":"","clientSheet":"https://docs.google.com/document/d/1J8rjP_ZD1BaiA3tFEw3DaUhlM2d8sWfXOfNpSguHq28/edit?tab=t.0","comments":[{"id":"comment-20-0-2-0","author":"Ben Lowe","text":"? have you even started this @Janin Canonero","timestamp":"2025-09-22T06:54:52","avatar":""},{"id":"comment-20-0-2-1","author":"Janin Canonero","text":"the file is ready for your review","timestamp":"2025-09-22T12:22:51","avatar":""},{"id":"comment-20-0-2-2","author":"Ben Lowe","text":"still not in ben to check","timestamp":"2025-09-22T12:24:39","avatar":""},{"id":"comment-20-0-2-3","author":"Ben Lowe","text":"@Janin Canonero Can you update this with reddit and quora questions, dont want any other site though.","timestamp":"2025-10-13T10:29:35","avatar":""},{"id":"comment-20-0-2-4","author":"Ben Lowe","text":"@Janin Canonero can you find some more for me","timestamp":"2025-10-20T02:00:42","avatar":""},{"id":"comment-20-0-2-5","author":"Janin Canonero","text":"@Ben Lowe  here's batch 2: https://docs.google.com/document/d/13PxuYBuvdo-197v_ipoV4VRVjgrnaDD-Gzlv9d9zkoc/edit?usp=sharing","timestamp":"2025-10-22T08:55:29","avatar":""},{"id":"comment-20-0-2-6","author":"Ben Lowe","text":"This needs doing @Janin Canonero Needs doing asap  most the questions have been archived","timestamp":"2025-11-12T18:44:57","avatar":""}]},{"id":"task-20-0-3","title":"Make thread see msg with chris","status":"status-5","priority":"priority-4","dueDate":"2025-09-23","assignedTo":"f9f11222-d2a9-4ae8-a327-8c4621d90b7c","worksheet":"","clientSheet":"","comments":[]},{"id":"task-20-0-4","title":"https://www.vestd.com/en-in/","status":"status-2","priority":"priority-4","dueDate":"2025-11-12","assignedTo":["a1e57188-a322-42b2-9d33-b5df08033685","f9f11222-d2a9-4ae8-a327-8c4621d90b7c"],"worksheet":"","clientSheet":"","comments":[{"id":"comment-20-0-4-0","author":"Janin Canonero","text":"@Ben We have operations in India and are looking to improve organic rankings for terms like 'ESOPs'.We have a fledgling India site here. We have existing pillar pages as per the footer, which tend to rank pretty well in the UK.Any ideas on how best to position these pillar pages for India, and what else we need to be doing in order to grow our rankings in that territory?@Steph can provide more detail on the website setup, and @Sparsh Johari is our marketing lead in India, and is best placed to coordinate on content creation / new web pages.","timestamp":"2025-10-13T17:04:27","avatar":""}]},{"id":"task-20-0-5","title":"Reddit questions batch 2","status":"status-6","priority":"priority-4","dueDate":"2025-11-12","assignedTo":"a1e57188-a322-42b2-9d33-b5df08033685","worksheet":"","clientSheet":"https://docs.google.com/document/d/1h7l2Z09TtohjApIoK056n-at8bgbe2MLBoF35EtFVp4/edit?tab=t.0","comments":[]}]},{"id":"group-20-1","title":"On-page","color":"#4ECDC4","tasks":[{"id":"task-20-1-0","title":"Meta and titles issues  Batch 2","status":"status-7","priority":"priority-4","dueDate":"2025-10-16","assignedTo":["a1e57188-a322-42b2-9d33-b5df08033685","cede181a-edf9-40fa-b917-e208ea15d450","01b597e9-43f0-4363-9ced-8b2613b1bbab","942055eb-54f6-426a-8194-b81ab83669f6"],"worksheet":"https://docs.google.com/spreadsheets/d/1ORGC3nF3LBVVR4d1rD0xR84I8qlXAdUr6B02RNO9xfo/edit?gid=0#gid=0","clientSheet":"https://docs.google.com/spreadsheets/d/11DBv5xJb-gmBmvfqHBdw3qNNxVNAliXfVHEJJ8l1_V0/edit?gid=983613307#gid=983613307","comments":[{"id":"comment-20-1-0-0","author":"Alyssa Marie Donayre","text":"@farhan nazardin , don't forget to do this, and observe deadlines.","timestamp":"2025-10-14T22:22:10","avatar":""},{"id":"comment-20-1-0-1","author":"Janin Canonero","text":"@farhan nazardin Be sure to carefully review the content on each page, as the client offers highly niche servi